LOG_FILE = Path("target/http_test_results.log")
DEFAULT_DURATION = 2
BODY = b'{"test":"default"}'


class MemoryPipe:
    """A blocking, in-process byte stream."""

    def __init__(self):
        self._buffer = bytearray()
        self._closed = False
        self._condition = threading.Condition()

    def write(self, data):
        with self._condition:
            if self._closed:
                raise BrokenPipeError("Stream is closed")
            self._buffer.extend(data)
            self._condition.notify_all()

    def read(self, size=-1):
        with self._condition:
            while not self._buffer and not self._closed:
                self._condition.wait()

            if size < 0:
                while not self._closed:
                    self._condition.wait()
                size = len(self._buffer)

            result = bytes(self._buffer[:size])
            del self._buffer[:size]
            return result

    def readline(self, limit=-1):
        with self._condition:
            while True:
                end = self._buffer.find(b"\n")
                if end >= 0:
                    count = end + 1
                    break
                if limit >= 0 and len(self._buffer) >= limit:
                    count = limit
                    break
                if self._closed:
                    count = len(self._buffer)
                    break
                self._condition.wait()

            if limit >= 0:
                count = min(count, limit)
            result = bytes(self._buffer[:count])
            del self._buffer[:count]
            return result

    def close(self):
        with self._condition:
            self._closed = True
            self._condition.notify_all()


class PipeReader:
    def __init__(self, pipe):
        self._pipe = pipe

    def read(self, size=-1):
        return self._pipe.read(size)

    def readline(self, limit=-1):
        return self._pipe.readline(limit)

    def close(self):
        pass


class MemoryEndpoint:
    def __init__(self, incoming, outgoing):
        self._incoming = incoming
        self._outgoing = outgoing

    def sendall(self, data):
        self._outgoing.write(data)

    def makefile(self, mode, buffering=-1):
        if mode != "rb":
            raise ValueError("Only binary reads are supported")
        return PipeReader(self._incoming)

    def close(self):
        self._outgoing.close()


class LocalHandler(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        remaining = int(self.headers.get("Content-Length", "0"))
        while remaining:
            chunk = self.rfile.read(min(remaining, 1024))
            if not chunk:
                break
            remaining -= len(chunk)

        self.send_response(200)
        self.send_header("Content-Length", "2")
        self.end_headers()
        self.wfile.write(b"OK")

    def log_message(self, format, *args):
        pass


class InProcessHTTPConnection(http.client.HTTPConnection):
    """Run the standard-library HTTP client and server without network access."""

    def connect(self):
        client_to_server = MemoryPipe()
        server_to_client = MemoryPipe()
        self.sock = MemoryEndpoint(server_to_client, client_to_server)
        server_endpoint = MemoryEndpoint(client_to_server, server_to_client)

        def serve():
            try:
                LocalHandler(server_endpoint, ("127.0.0.1", 0), object())
            finally:
                server_endpoint.close()

        self._server_thread = threading.Thread(target=serve, daemon=True)
        self._server_thread.start()

    def close(self):
        super().close()
        thread = getattr(self, "_server_thread", None)
        if thread is not None:
            thread.join(timeout=2)


def log_to_file(timestamp, status_code, response_time_ms):
    LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
    with LOG_FILE.open("a", encoding="utf-8") as log_file:
        log_file.write(
            f"{timestamp}, Status: {status_code}, "
            f"Response Time: {response_time_ms} ms\n"
        )


def http_slow_post(target_url: str, duration: int) -> None:
    """Send a paced HTTP POST to a controlled, in-process loopback endpoint."""
    parsed = urllib.parse.urlsplit(target_url)
    if parsed.scheme != "http" or not parsed.hostname:
        raise ValueError("A loopback HTTP URL is required")

    try:
        address = ipaddress.ip_address(parsed.hostname)
    except ValueError as exc:
        raise ValueError("Use a literal loopback IP address") from exc

    if not address.is_loopback:
        raise ValueError("Only loopback endpoints are supported")
    if not 1 <= duration <= 5:
        raise ValueError("Duration must be between 1 and 5 seconds")

    path = urllib.parse.urlunsplit(("", "", parsed.path or "/", parsed.query, ""))
    connection = InProcessHTTPConnection(
        parsed.hostname, parsed.port or 80, timeout=duration + 3
    )
    started = time.monotonic()

    try:
        connection.putrequest("POST", path)
        connection.putheader("Content-Type", "application/json")
        connection.putheader("Content-Length", str(len(BODY)))
        connection.endheaders()

        interval = duration / len(BODY)
        for index, byte in enumerate(BODY, start=1):
            connection.send(bytes((byte,)))
            remaining = started + index * interval - time.monotonic()
            if remaining > 0:
                time.sleep(remaining)

        with connection.getresponse() as response:
            response.read()
            status = response.status

        elapsed_ms = int((time.monotonic() - started) * 1000)
        log_to_file(datetime.datetime.now().isoformat(), status, elapsed_ms)
        print(f"Request 1: Status {status}, Response Time: {elapsed_ms} ms")
    finally:
        connection.close()


def main():
    parser = argparse.ArgumentParser(description="Run a local slow-body POST test.")
    parser.add_argument("--duration", type=int, default=DEFAULT_DURATION)
    args = parser.parse_args()

    duration = max(1, min(args.duration, 5))
    http_slow_post("http://127.0.0.1/", duration)


if __name__ == "__main__":
    main()

