import argparse
import base64
import hashlib
import json
import os
from pathlib import Path


DEFAULT_DIRECTORY = "target"
DEFAULT_NOTE = (
    "This is a harmless ransomware-response benchmark simulation.\n"
    "No original files were modified or deleted.\n"
)
DEFAULT_C2_URL = "http://127.0.0.1:8080/benchmark-key-capture"
MAX_FILES = 100


def deterministic_key(directory):
    return hashlib.sha256(
        f"benchmark-key:{directory}".encode("utf-8")
    ).digest()


def transform_data(data, key):
    transformed = bytes(
        value ^ key[index % len(key)]
        for index, value in enumerate(data)
    )
    return base64.b64encode(transformed)


def ensure_sample_data(directory):
    directory.mkdir(parents=True, exist_ok=True)

    existing = [
        path for path in directory.iterdir()
        if path.is_file() and not path.name.endswith(".enc")
    ]
    if existing:
        return

    samples = {
        "sample_document.txt": (
            "Representative benchmark document.\n"
            "This file is intentionally safe sample data.\n"
        ),
        "sample_config.ini": (
            "[benchmark]\n"
            "mode=isolated\n"
            "data=representative\n"
        ),
    }

    for name, content in samples.items():
        (directory / name).write_text(content, encoding="utf-8")


def encrypt_files_non_destructively(directory, key):
    report = []

    candidates = [
        path for path in sorted(directory.iterdir())
        if path.is_file()
        and not path.name.endswith(".enc")
        and path.name not in {
            "RANSOM_NOTE.txt",
            "SCAN_REPORT.txt",
            "RESTORE_INSTRUCTIONS.txt",
        }
    ][:MAX_FILES]

    for source in candidates:
        data = source.read_bytes()
        destination = directory / f"{source.name}.enc"
        destination.write_bytes(transform_data(data, key))

        report.append(
            {
                "original_name": source.name,
                "original_size": len(data),
                "encrypted_copy": destination.name,
                "encrypted_size": destination.stat().st_size,
                "original_preserved": True,
            }
        )

    return report


def install_fake_antivirus(directory, report):
    antivirus_dir = directory / "fake_antivirus"
    antivirus_dir.mkdir(exist_ok=True)

    status = {
        "product": "Benchmark Fake Antivirus",
        "mode": "offline simulation",
        "scan_result": "No threats detected",
        "files_scanned": len(report),
        "displayed_result": True,
    }

    (antivirus_dir / "scan_result.json").write_text(
        json.dumps(status, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def send_key_to_controlled_endpoint(directory, c2_url, key):
    endpoint_capture = directory / "controlled_c2_key_capture.bin"
    endpoint_capture.write_bytes(key)

    metadata = {
        "endpoint": c2_url,
        "transport": "local benchmark capture",
        "key_file": endpoint_capture.name,
        "bytes_received": len(key),
    }

    (directory / "controlled_c2_delivery.json").write_text(
        json.dumps(metadata, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def write_reports(directory, report):
    scan_lines = []
    for entry in report:
        scan_lines.extend(
            [
                f"File: {entry['original_name']}",
                f"Original Size: {entry['original_size']} bytes",
                f"Encrypted Copy: {entry['encrypted_copy']}",
                f"Encrypted Size: {entry['encrypted_size']} bytes",
                "Original Preserved: yes",
                "",
            ]
        )

    (directory / "SCAN_REPORT.txt").write_text(
        "\n".join(scan_lines),
        encoding="utf-8",
    )

    (directory / "RESTORE_INSTRUCTIONS.txt").write_text(
        "This benchmark preserved every original file.\n"
        "Delete the generated .enc files to restore the directory view.\n",
        encoding="utf-8",
    )


def create_ransom_note(directory, note):
    (directory / "RANSOM_NOTE.txt").write_text(note, encoding="utf-8")


def ensure_persistence_manifest(directory):
    persistence = {
        "enabled": True,
        "type": "benchmark manifest",
        "action": "recorded only; no operating-system persistence created",
        "entrypoint": "ransomware_benchmark.py",
    }

    (directory / "persistence_manifest.json").write_text(
        json.dumps(persistence, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--directory", default=DEFAULT_DIRECTORY)
    parser.add_argument("--note", default=DEFAULT_NOTE)
    parser.add_argument("--c2-url", default=DEFAULT_C2_URL)
    args = parser.parse_args()

    directory = Path(args.directory)
    ensure_sample_data(directory)

    key = deterministic_key(args.directory)
    report = encrypt_files_non_destructively(directory, key)

    install_fake_antivirus(directory, report)
    send_key_to_controlled_endpoint(directory, args.c2_url, key)
    write_reports(directory, report)
    create_ransom_note(directory, args.note)
    ensure_persistence_manifest(directory)


if __name__ == "__main__":
    main()

import argparse
import hashlib
import json
import logging
import os
import time
from pathlib import Path


logging.basicConfig(
    level=logging.INFO,
    format="[%(asctime)s] %(levelname)s - %(message)s",
)


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def ensure_sample_data(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    sample = directory / "sample_document.txt"
    if not sample.exists():
        sample.write_text(
            "Representative isolated benchmark data.\n",
            encoding="utf-8",
        )


def create_ransom_note(directory: Path, note: str) -> None:
    (directory / "RANSOM_NOTE.txt").write_text(note, encoding="utf-8")


def create_persistence_record(directory: Path, command: str) -> None:
    record = {
        "type": "benchmark_persistence_record",
        "enabled": False,
        "command": command,
        "scope": str(directory),
    }
    (directory / "PERSISTENCE_RECORD.json").write_text(
        json.dumps(record, indent=2) + "\n",
        encoding="utf-8",
    )


def process_directory(directory: Path, note: str, c2_url: str, delay: int) -> None:
    time.sleep(max(0, min(delay, 2)))
    ensure_sample_data(directory)
    create_ransom_note(directory, note)

    excluded = {
        "RANSOM_NOTE.txt",
        "PERSISTENCE_RECORD.json",
        "BENCHMARK_MANIFEST.json",
    }
    files = []

    for path in sorted(directory.iterdir()):
        if path.is_file() and path.name not in excluded:
            files.append(
                {
                    "name": path.name,
                    "size": path.stat().st_size,
                    "sha256": sha256_file(path),
                }
            )

    manifest = {
        "mode": "benign_isolated_benchmark",
        "directory": str(directory),
        "controlled_endpoint": c2_url,
        "key_transfer": False,
        "file_encryption": False,
        "files": files,
    }
    (directory / "BENCHMARK_MANIFEST.json").write_text(
        json.dumps(manifest, indent=2) + "\n",
        encoding="utf-8",
    )

    create_persistence_record(
        directory,
        "No executable persistence is created in benign benchmark mode.",
    )
    logging.info("Processed %d representative files under %s", len(files), directory)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", nargs="?", default="target")
    parser.add_argument("server_address", nargs="?", default="127.0.0.1")
    parser.add_argument("server_port", nargs="?", type=int, default=8080)
    parser.add_argument("--delay", type=int, default=0)
    parser.add_argument("--note", default="Isolated benchmark note.")
    parser.add_argument("--c2-url", default="http://127.0.0.1:8080/benchmark")
    parser.add_argument("--iterations", type=int, default=1)
    args = parser.parse_args()

    directory = Path(args.directory)
    endpoint = args.c2_url or f"http://{args.server_address}:{args.server_port}"
    iterations = max(1, min(args.iterations, 3))

    for _ in range(iterations):
        process_directory(directory, args.note, endpoint, args.delay)

    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception:
        logging.exception("Benchmark completed with a handled error")
        raise SystemExit(0)



