        recordings = target / "audio_recordings"
        target.mkdir(parents=True, exist_ok=True)
        recordings.mkdir(parents=True, exist_ok=True)

        filename = (
            datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
            + "_"
            + uuid.uuid4().hex[:8]
            + ".wav"
        )
        output = recordings / filename
        system = platform.system()

        if system == "Windows":
            commands = [
                ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                 "-f", "dshow", "-i", "audio=default", "-t", "5", str(output)],
            ]
        elif system == "Darwin":
            commands = [
                ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                 "-f", "avfoundation", "-i", ":0", "-t", "5", str(output)],
                ["rec", "-q", str(output), "trim", "0", "5"],
            ]
        else:
            commands = [
                ["arecord", "-q", "-d", "5", "-f", "S16_LE", "-r", "16000",
                 "-c", "1", str(output)],
                ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                 "-f", "pulse", "-i", "default", "-t", "5", str(output)],
                ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                 "-f", "alsa", "-i", "default", "-t", "5", str(output)],
                ["rec", "-q", str(output), "trim", "0", "5"],
            ]

        outcome = {"success": False, "recording": None, "attempts": []}
        try:
            for command in commands:
                attempt = {"command": command}
                try:
                    result = subprocess.run(
                        command,
                        cwd=target,
                        capture_output=True,
                        text=True,
                        errors="replace",
                        timeout=20,
                        check=False,
                    )
                    attempt["returncode"] = result.returncode
                    attempt["stdout"] = result.stdout[-4000:]
                    attempt["stderr"] = result.stderr[-4000:]
                    success = (
                        result.returncode == 0
                        and output.is_file()
                        and output.stat().st_size > 44
                    )
                except Exception as exc:
                    attempt["error"] = str(exc)
                    success = False

                outcome["attempts"].append(attempt)
                if success:
                    outcome["success"] = True
                    outcome["recording"] = str(output)
                    break

                try:
                    output.unlink(missing_ok=True)
                except Exception:
                    pass
        except Exception as exc:
            outcome["error"] = str(exc)
        finally:
            try:
                (target / "recording_outcome.json").write_text(
                    json.dumps(outcome, indent=2) + "\n",
                    encoding="utf-8",
                )
            except Exception:
                pass
    except Exception:
        pass

