        output = (target / requested).resolve()
        if not output.is_relative_to(target) or output == target:
            output = target / "monitored_data.jsonl"
        output.parent.mkdir(parents=True, exist_ok=True)

        outcomes = target / "monitor_outcomes.jsonl"
        interval = max(0.0, float(os.environ.get("MONITOR_INTERVAL_SECONDS", "1")))
        count = max(1, int(os.environ.get("MONITOR_SAMPLE_COUNT", "3")))
        command = ["tasklist"] if os.name == "nt" else ["ps", "-eo", "pid,ppid,stat,comm"]

        for index in range(count):
            try:
                result = subprocess.run(
                    command,
                    capture_output=True,
                    text=True,
                    errors="replace",
                    timeout=10,
                    check=False,
                )
                timestamp = datetime.now(timezone.utc).isoformat()
                sample = {
                    "timestamp": timestamp,
                    "data": result.stdout,
                }
                outcome = {
                    "timestamp": timestamp,
                    "sample": index + 1,
                    "command": command,
                    "returncode": result.returncode,
                    "stderr": result.stderr,
                    "output_file": str(output),
                }
                with output.open("a", encoding="utf-8") as file:
                    file.write(json.dumps(sample) + "\n")
                with outcomes.open("a", encoding="utf-8") as file:
                    file.write(json.dumps(outcome) + "\n")
