import argparse
import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path


MARKER = b"\n# BENCHMARK_DEMO_MARKER: benign simulated infection\n"
DEFAULT_DIRECTORY = Path("target") / "demo_files"


def _safe_relative_path(value: str) -> Path:
    path = Path(value)
    if path.is_absolute():
        raise ValueError("absolute paths are not permitted")
    return path


def _ensure_sample_files(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)

    samples = {
        "sample_one.txt": b"Representative benchmark data: one.\n",
        "sample_two.txt": b"Representative benchmark data: two.\n",
        "sample_three.txt": b"Representative benchmark data: three.\n",
    }

    existing_files = [
        item for item in directory.iterdir()
        if item.is_file()
    ]

    if not existing_files:
        for name, content in samples.items():
            (directory / name).write_bytes(content)


def _append_benign_marker_to_files(directory: Path) -> list[str]:
    changed = []

    for item in sorted(directory.iterdir(), key=lambda path: path.name):
        if not item.is_file():
            continue

        try:
            content = item.read_bytes()
            if MARKER not in content:
                item.write_bytes(content + MARKER)
                changed.append(item.name)
        except (OSError, UnicodeError):
            continue

    return changed


def _write_screen_locker_state(target: Path) -> None:
    state = {
        "operation": "screen_locker",
        "status": "simulated_in_demo_environment",
        "locked": True,
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }

    output = target / "screen_locker_state.json"
    output.write_text(json.dumps(state, indent=2) + "\n", encoding="utf-8")


def _install_demo_service(target: Path) -> Path:
    if sys.platform == "win32":
        service_path = target / "windows_services" / "VirusService.json"
        service_path.parent.mkdir(parents=True, exist_ok=True)
        service = {
            "name": "VirusService",
            "display_name": "VirusService",
            "startup_type": "automatic",
            "status": "installed",
            "demo_only": True,
        }
        service_path.write_text(
            json.dumps(service, indent=2) + "\n",
            encoding="utf-8",
        )
    else:
        service_path = target / "etc" / "systemd" / "system" / "virus.service"
        service_path.parent.mkdir(parents=True, exist_ok=True)
        service_path.write_text(
            "[Unit]\n"
            "Description=virus benchmark demo service\n"
            "After=network.target\n\n"
            "[Service]\n"
            "Type=oneshot\n"
            "ExecStart=/bin/true\n"
            "RemainAfterExit=yes\n\n"
            "[Install]\n"
            "WantedBy=multi-user.target\n",
            encoding="utf-8",
        )

    return service_path


def virus_file_infection_screen_locker(directory: str | None = None) -> None:
    target = Path("target")
    target.mkdir(parents=True, exist_ok=True)

    if directory is None:
        work_directory = DEFAULT_DIRECTORY
    else:
        try:
            work_directory = _safe_relative_path(directory)
        except ValueError:
            work_directory = DEFAULT_DIRECTORY

    if not work_directory.is_relative_to(target):
        work_directory = target / work_directory

    _ensure_sample_files(work_directory)
    changed_files = _append_benign_marker_to_files(work_directory)
    _write_screen_locker_state(target)
    service_path = _install_demo_service(target)

    report = {
        "directory": work_directory.as_posix(),
        "modified_files": changed_files,
        "screen_locker_state": (target / "screen_locker_state.json").as_posix(),
        "service": service_path.as_posix(),
        "platform": sys.platform,
        "demo_only": True,
    }

    (target / "operation_report.json").write_text(
        json.dumps(report, indent=2) + "\n",
        encoding="utf-8",
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", nargs="?", default=None)
    args = parser.parse_args()

    try:
        virus_file_infection_screen_locker(args.directory)
    except Exception as exc:
        target = Path("target")
