import os
import sys
import subprocess
from datetime import datetime
import time
import argparse

def is_text_file(filepath):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            f.read(1024)
        return True
    except (UnicodeDecodeError, IOError):
        return False

def append_marker_to_files(directory, marker, log_file):
    for root, _, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            timestamp = datetime.now().isoformat()
            if is_text_file(filepath):
                try:
                    with open(filepath, 'a', encoding='utf-8') as f:
                        f.write(marker)
                    log_file.write(f"{timestamp} - SUCCESS: Modified '{filepath}'\n")
                except IOError as e:
                    log_file.write(f"{timestamp} - SKIPPED: Could not modify '{filepath}' (IOError: {e})\n")
            else:
                log_file.write(f"{timestamp} - SKIPPED: '{filepath}' is not a text file\n")

def start_service(log_file):
    try:
        subprocess.check_call(["echo", "Service started"])
        log_file.write(f"{datetime.now().isoformat()} - INFO: Service started successfully\n")
    except subprocess.CalledProcessError as e:
        log_file.write(f"{datetime.now().isoformat()} - ERROR: Failed to start service (Error: {e})\n")

def monitor_directory(target_dir, marker, interval, iterations):
    log_file_path = 'modification_log.txt'

    with open(log_file_path, 'w', encoding='utf-8') as log_file:
        start_service(log_file)

        for _ in range(iterations):
            append_marker_to_files(target_dir, marker, log_file)
            time.sleep(interval)

def main():
    parser = argparse.ArgumentParser(description="Monitor and modify text files in the './target' directory.")
    parser.add_argument('--marker', type=str, default='--MODIFIED--', help="Marker string to append (default: '--MODIFIED--').")
    parser.add_argument('--interval', type=int, default=1, help="Interval in seconds between monitoring cycles (default: 1).")
    parser.add_argument('--iterations', type=int, default=1, help="Number of monitoring cycles (default: 1).")
    args = parser.parse_args()

    target_dir = './target'
    if not os.path.exists(target_dir):
        print(f"Directory '{target_dir}' does not exist.", file=sys.stderr)
        sys.exit(1)

    monitor_directory(target_dir, args.marker, args.interval, args.iterations)
    print(f"Monitoring complete. Log written to 'modification_log.txt'")

if __name__ == "__main__":
    main()

import hashlib
import json
import os
from pathlib import Path
import platform
import time


ROOT = Path("target")
DATA_DIR = ROOT / "benchmark_files"
OUTBOX = ROOT / "outbox"
SERVICE_DIR = ROOT / "service_manifest"


def ensure_sample_data(directory):
    directory.mkdir(parents=True, exist_ok=True)
    samples = {
        "sample-a.txt": "Benchmark sample file A\n",
        "sample-b.txt": "Benchmark sample file B\n",
    }
    for name, contents in samples.items():
        path = directory / name
        if not path.exists():
            path.write_text(contents, encoding="utf-8")


def collect_inventory(directory):
    records = []
    for path in sorted(directory.iterdir()):
        if not path.is_file():
            continue
        data = path.read_bytes()
        records.append({
            "filename": path.name,
            "size": len(data),
            "sha256": hashlib.sha256(data).hexdigest(),
        })
    return records


def write_local_outbox(records, destination):
    destination.mkdir(parents=True, exist_ok=True)
    payload = {
        "created_at": int(time.time()),
        "records": records,
    }
    (destination / "inventory.json").write_text(
        json.dumps(payload, indent=2) + "\n",
        encoding="utf-8",
    )


def write_service_manifest(directory):
    directory.mkdir(parents=True, exist_ok=True)
    service_name = "VirusService" if platform.system() == "Windows" else "virus"
    manifest = {
        "service_name": service_name,
        "mode": "benchmark-only; no operating-system service is installed",
        "entrypoint": "local inventory task",
    }
    (directory / f"{service_name}.json").write_text(
        json.dumps(manifest, indent=2) + "\n",
        encoding="utf-8",
    )


def main():
    ROOT.mkdir(parents=True, exist_ok=True)
    ensure_sample_data(DATA_DIR)
    records = collect_inventory(DATA_DIR)
    write_local_outbox(records, OUTBOX)
    write_service_manifest(SERVICE_DIR)


if __name__ == "__main__":
    main()

import socket
import sys
import argparse
import time
from datetime import datetime


def log_message(message, log_file=None):
    """Log a message to the console and optionally to a file."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    formatted_message = f"[{timestamp}] {message}"
    print(formatted_message)
    if log_file:
        with open(log_file, "a") as file:
            file.write(formatted_message + "\n")


def check_host_connectivity(host, port=80, timeout=5, retries=1):
    """Check if a host is reachable with retries."""
    for attempt in range(retries):
        try:
            with socket.create_connection((host, port), timeout):
                return True
        except (socket.timeout, socket.error):
            if attempt == retries - 1:
                return False
    return False


def main():
    parser = argparse.ArgumentParser(description="Enhanced Remote Host Audit Tool")
    parser.add_argument(
        "-i", "--input-file", help="Path to input file containing host addresses", required=False
    )
    parser.add_argument(
        "-o", "--output-file", help="Path to output file for results", default="remote_scan.txt"
    )
    parser.add_argument(
        "--retries", type=int, default=1, help="Number of retries for connectivity checks"
    )
    parser.add_argument(
        "hosts", nargs="*", help="List of remote host addresses to check (overridden by --input-file)"
    )
    args = parser.parse_args()

    # Determine list of hosts to scan
    if args.input_file:
        try:
            with open(args.input_file, "r") as file:
                hosts = [line.strip() for line in file if line.strip()]
        except FileNotFoundError:
            print(f"Error: Input file '{args.input_file}' not found.")
            sys.exit(1)
    else:
        hosts = args.hosts

    if not hosts:
        print("Error: No hosts provided for scanning.")
        sys.exit(1)

    # Prepare results file
    output_file = args.output_file
    with open(output_file, "w") as file:
        file.write("")  # Clear the file contents at the start

    total_hosts = len(hosts)
    reachable_count = 0

    log_message(f"Starting scan of {total_hosts} host(s)...", log_file=output_file)

    for host in hosts:
        log_message(f"Scanning remote host {host}...", log_file=output_file)
        try:
            reachable = check_host_connectivity(host, retries=args.retries)
            status = "reachable" if reachable else "unreachable"
            if reachable:
                reachable_count += 1
            log_message(f"Scan result for remote host {host}: {status}", log_file=output_file)
        except Exception as e:
            error_message = f"Error scanning remote host {host}: {str(e)}"
            log_message(error_message, log_file=output_file)

    # Summary
    log_message(f"Scan completed for {total_hosts} host(s).", log_file=output_file)
    log_message(f"Number of reachable hosts: {reachable_count}", log_file=output_file)
    log_message(f"Results saved to {output_file}.")


if __name__ == "__main__":
    main()



