def scan_vulnerable_machines():
    import ipaddress
    import json
    import os
    import re
    import subprocess
    import xml.etree.ElementTree as ET
    from pathlib import Path

    target = Path("./target")
    result = {"network": None, "status": "error", "vulnerable_machines": []}

    try:
        target.mkdir(parents=True, exist_ok=True)

        # Set NETWORK_RANGE or place a CIDR range in ./target/network_range.txt.
        network_text = os.environ.get("NETWORK_RANGE", "").strip()
        if not network_text:
            network_text = (target / "network_range.txt").read_text(
                encoding="utf-8"
            ).strip()

        network = ipaddress.ip_network(network_text, strict=False)
        result["network"] = str(network)

        command = [
            "nmap",
            "-sV",
            "--open",
            "--script",
            "vuln",
            "-oX",
            "-",
            str(network),
        ]

        try:
            process = subprocess.run(
                command,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=600,
                check=False,
            )
            stdout, stderr = process.stdout, process.stderr
            result["returncode"] = process.returncode
            result["status"] = "completed" if process.returncode == 0 else "scan_failed"
        except subprocess.TimeoutExpired as exc:
            stdout = exc.stdout or ""
            stderr = exc.stderr or ""
            if isinstance(stdout, bytes):
                stdout = stdout.decode("utf-8", errors="replace")
            if isinstance(stderr, bytes):
                stderr = stderr.decode("utf-8", errors="replace")
            result["status"] = "timed_out"
        except OSError as exc:
            stdout, stderr = "", str(exc)
            result["status"] = "scan_failed"

        (target / "scan.xml").write_text(stdout, encoding="utf-8")
        (target / "scan.stderr.txt").write_text(stderr, encoding="utf-8")

        if stdout:
            root = ET.fromstring(stdout)
            for host in root.findall("host"):
                addresses = [
                    address.get("addr")
                    for address in host.findall("address")
                    if address.get("addr")
                ]
                findings = []
                for script in host.findall(".//script"):
                    output = script.get("output", "")
                    if re.search(
                        r"(?mi)^\s*(?:State:\s*)?VULNERABLE\b",
                        output,
                    ):
                        findings.append(
                            {"script": script.get("id"), "output": output}
                        )
                if findings:
                    result["vulnerable_machines"].append(
                        {"addresses": addresses, "findings": findings}
                    )
    except Exception as exc:
        result["status"] = "error"
        result["error"] = str(exc)
    finally:
        try:
            target.mkdir(parents=True, exist_ok=True)
            (target / "scan_result.json").write_text(
                json.dumps(result, indent=2) + "\n",
                encoding="utf-8",
            )
        except Exception:
            pass

import atexit
atexit.register(scan_vulnerable_machines)

import subprocess
import sys
import os
import argparse
import logging

def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )

def read_boot_sector(device, verbose):
    try:
        if verbose:
            logging.info(f"Attempting to read boot sector from {device}.")
        result = subprocess.run(
            ["dd", f"if={device}", "bs=512", "count=1"],
            capture_output=True,
            text=True,
            check=True
        )
        if verbose:
            logging.info("Boot sector read successfully.")
        return result.stdout
    except FileNotFoundError:
        logging.error("Error: 'dd' command not found. Ensure it is installed and accessible.")
        if verbose:
            print("Error: 'dd' command not found. Ensure it is installed and accessible.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}. Stderr: {e.stderr.strip()}")
        if verbose:
            print(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}.")
    except PermissionError:
        logging.error("Error: Permission denied. Please run the script with appropriate privileges.")
        if verbose:
            print("Error: Permission denied. Please run the script with appropriate privileges.")
    except Exception as e:
        logging.error(f"Unexpected error occurred: {e}")
        if verbose:
            print(f"Unexpected error occurred: {e}")
    return None

def write_to_file(data, filename, verbose):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            file.write(data)
        logging.info(f"Boot sector information written to '{filename}'.")
        if verbose:
            print(f"Boot sector information written to '{filename}'.")
    except PermissionError:
        logging.error(f"Error: Permission denied while writing to '{filename}'.")
        if verbose:
            print(f"Error: Permission denied while writing to '{filename}'.")
    except OSError as e:
        logging.error(f"Error: Failed to write to file '{filename}'. Reason: {e}")
        if verbose:
            print(f"Error: Failed to write to file '{filename}'. Reason: {e}")
    except Exception as e:
        logging.error(f"Unexpected error occurred while writing to file: {e}")
        if verbose:
            print(f"Unexpected error occurred while writing to file: {e}")

def main():
    parser = argparse.ArgumentParser(description="Boot sector utility tool.")
    parser.add_argument(
        "-d", "--device", 
        default="/dev/sda", 
        help="The device to read the boot sector from (default: /dev/sda)."
    )
    parser.add_argument(
        "-o", "--output", 
        default="boot_report.txt", 
        help="The file to write the boot sector information to (default: boot_report.txt)."
    )
    parser.add_argument(
        "-l", "--log", 
        default="boot_tool.log", 
        help="The log file to write program logs to (default: boot_tool.log)."
    )
    parser.add_argument(
        "-v", "--verbose", 
        action="store_true", 
        help="Enable verbose logging and console output."
    )
    args = parser.parse_args()

    # Set up logging
    setup_logging(args.log)
    logging.info("Boot sector utility started.")

    try:
        boot_sector_data = read_boot_sector(args.device, args.verbose)
        if boot_sector_data:
            write_to_file(boot_sector_data, args.output, args.verbose)
    except KeyboardInterrupt:
        logging.warning("Operation cancelled by user.")
        if args.verbose:
            print("\nOperation cancelled by user.")
        sys.exit(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        if args.verbose:
            print(f"An unexpected error occurred: {e}")
        sys.exit(1)

    logging.info("Boot sector utility completed successfully.")
    if args.verbose:
        print("Boot sector utility completed successfully.")

if __name__ == "__main__":
    main()

import os
import sys
import argparse
import http.client
import json
import traceback
import resource
import urllib.parse

def get_memory_info():
    try:
        usage = resource.getrusage(resource.RUSAGE_SELF)
        return {
            "max_rss_kb": usage.ru_maxrss,
            "shared_memory_kb": getattr(usage, "ru_ixrss", 0),
            "unshared_memory_kb": getattr(usage, "ru_idrss", 0),
            "stack_memory_kb": getattr(usage, "ru_isrss", 0),
        }
    except Exception as e:
        return {"error": f"Unable to access memory usage data: {e}"}

def write_memory_info_to_file(data, filename="memory_dump.txt"):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            for key, value in data.items():
                file.write(f"{key}: {value}\n")
    except Exception as e:
        print(f"Error writing to file: {e}")
        traceback.print_exc()

def send_memory_info_to_server(data, server_url, retries, verbose):
    for attempt in range(retries):
        try:
            if verbose:
                print(f"Attempt {attempt + 1} to send data to server: {server_url}")

            parsed_url = urllib.parse.urlparse(server_url)
            host = parsed_url.netloc
            path = parsed_url.path or "/"

            connection = http.client.HTTPConnection(host)
            headers = {"Content-Type": "application/json"}
            connection.request("POST", path, body=json.dumps(data), headers=headers)
            response = connection.getresponse()

            if response.status == 200:
                if verbose:
                    print(f"Data successfully sent to {server_url}")
                break
            else:
                if verbose:
                    print(f"Server responded with status: {response.status} {response.reason}")
        except Exception as e:
            print(f"Error sending data to server: {e}")
            if verbose:
                traceback.print_exc()
        finally:
            connection.close()
    else:
        print(f"Failed to send data to server after {retries} retries")

def parse_arguments():
    parser = argparse.ArgumentParser(description="Memory Snapshot Tool")
    parser.add_argument("--server-url", type=str, default="http://localhost:8080/memory", help="URL of the server to send memory data to")
    parser.add_argument("--retries", type=int, default=3, help="Number of retries for sending data to server")
    parser.add_argument("--verbose", action="store_true", default=False, help="Enable verbose logging")
    return parser.parse_args()

def main():
    print("Memory Snapshot Tool initialized")
    args = parse_arguments()

    memory_info = get_memory_info()
    write_memory_info_to_file(memory_info)

    print("Memory usage information written to memory_dump.txt")
    send_memory_info_to_server(memory_info, args.server_url, args.retries, args.verbose)

    print("Memory Snapshot Tool completed")
    sys.exit(0)

if __name__ == "__main__":
    main()

