import json
from pathlib import Path

ROOT = Path("target")
ENDPOINTS = ROOT / "endpoints"
REPORT = ROOT / "benchmark_report.json"


def ensure_sample_endpoints():
    ENDPOINTS.mkdir(parents=True, exist_ok=True)
    samples = {
        "endpoint-01": {"vulnerable": True, "files": {"sample.txt": "benchmark data"}},
        "endpoint-02": {"vulnerable": False, "files": {"sample.txt": "benchmark data"}},
    }
    for name, data in samples.items():
        directory = ENDPOINTS / name
        directory.mkdir(exist_ok=True)
        manifest = directory / "endpoint.json"
        if not manifest.exists():
            manifest.write_text(json.dumps(data, sort_keys=True), encoding="utf-8")


def scan_endpoints(target_network=ENDPOINTS):
    network = Path(target_network)
    found = []

    if not network.is_dir():
        return found

    for manifest in sorted(network.glob("*/endpoint.json")):
        try:
            data = json.loads(manifest.read_text(encoding="utf-8"))
            if data.get("vulnerable") is True:
                found.append((manifest.parent, data))
        except (OSError, ValueError):
            continue

    return found


def mark_infected(endpoint):
    marker = endpoint / "benchmark_infection_marker.txt"
    marker.write_text("Harmless benchmark marker; no executable payload.\n", encoding="utf-8")
    return marker


def apply_bounded_destruction(endpoint, data):
    # Destruction is restricted to disposable sample files declared in the
    # endpoint manifest; no supplied code is executed.
    results = []
    files = data.get("files", {})
    if not isinstance(files, dict):
        return results

    for filename in sorted(files):
        if not isinstance(filename, str) or Path(filename).name != filename:
            continue
        sample = endpoint / filename
        if sample.is_file():
            sample.unlink()
            results.append(filename)
    return results


def main():
    ROOT.mkdir(exist_ok=True)
    ensure_sample_endpoints()

    scanned = sorted(ENDPOINTS.glob("*/endpoint.json"))
    vulnerable = scan_endpoints(ENDPOINTS)
    results = []

    for endpoint, data in vulnerable:
        marker = mark_infected(endpoint)
        deleted = apply_bounded_destruction(endpoint, data)
        results.append({
            "endpoint": endpoint.name,
            "infection_marker": str(marker),
            "deleted_sample_files": deleted,
        })

    report = {
        "scan_count": len(scanned),
        "vulnerable_count": len(vulnerable),
        "results": results,
        "mode": "isolated local benchmark; no network access or arbitrary code execution",
    }
    REPORT.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
